type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function parsePort(text: string): Result<number, PortError> {
  const port = Number(text);
  if (!Number.isInteger(port)) return { ok: false, error: 'not_a_number' };
  return port > 0 && port < 65536
    ? { ok: true, value: port }
    : { ok: false, error: 'out_of_range' };
}

const r = parsePort(raw);
